mapper.update:
UPDATE assistant_agent_action
SET status = 'CANCELLED', update_time = #{updateTime}
WHERE agent_task_id = #{agentTaskId}
  AND status IN ('PROPOSED', 'WAITING_CONFIRMATION', 'CONFIRMED')

UPDATE assistant_agent_action
SET status = 'CANCELLED', update_time = #{updateTime}
WHERE agent_task_id = #{agentTaskId}
  AND action_type = 'CREATE_FOLLOW_UP_COLLECTION_TASK'
  AND status IN ('PROPOSED', 'WAITING_CONFIRMATION')

UPDATE assistant_agent_action
SET status = 'EXECUTING', update_time = #{updateTime}, version = version + 1
WHERE id = #{id}
  AND status = 'CONFIRMED'
  AND version = #{expectedVersion}

UPDATE assistant_agent_action
SET status = 'FAILED', error_message = #{errorMessage},
    update_time = #{updateTime}, version = version + 1
WHERE id = #{id}
  AND status IN ('WAITING_CONFIRMATION', 'CONFIRMED', 'EXECUTING')
  AND version = #{expectedVersion}
